def path(route: str, **params: str) -> str:
    """The path a route of ROUTES answers at, each of its parameters filled and escaped."""
    if route not in ROUTES:
        raise ValueError(f"{route!r} is not a route serve mounts")
    out = []
    for segment in route.split(" ", 1)[1].split("/"):
        if segment.startswith("{") and segment.endswith("}"):
            name = segment[1:-1]
            if name not in params:
                raise ValueError(f"{route!r} needs {name}")
            segment = urllib.parse.quote(str(params.pop(name)), safe="")
        out.append(segment)
    if params:
        raise ValueError(f"{route!r} has no parameter {', '.join(sorted(params))}")
    return "/".join(out)
